import json
x=json.load(open('contracts/openapi.contract.json'))
for p,ps in x['paths'].items():
 for meth,o in ps.items():
  if not isinstance(o,dict):continue
  print('\n###',meth.upper(),p,o['operationId'])
  rb=o.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema',{})
  if rb: print('REQ',json.dumps(rb, separators=(',',':')))
  for k,v in o.get('responses',{}).items():
   s=v.get('content',{}).get('application/json',{}).get('schema',{})
   print('RES',k,json.dumps(s,separators=(',',':'))[:1000])
PY

