func generic(w http.ResponseWriter,p string,q M){if p=="create-connection"{x:=id();q["connectionId"]=x;q["id"]=x;q["capacity"]=cap(0);st.Connections[x]=q;reply(w,201,M{"data":q});return};if p=="set-location-status"||p=="set-location-function-status"||p=="update-location"{l:=st.Locations[fmt.Sprint(q["locationId"])];if l==nil{fail(w,404,"not_found");return};if p=="set-location-status"{l["active"]=q["active"]};if p=="set-location-function-status"{l["functions"].(M)[fmt.Sprint(q["function"])]=q["active"]};for k,v:=range q{if k!="locationId"{l[k]=v}};reply(w,201,M{"data":l});return};if p=="set-connection-status"{c:=st.Connections[fmt.Sprint(q["connectionId"])];if c==nil{fail(w,404,"not_found");return};c["active"]=q["active"];reply(w,200,M{"data":M{"connectionId":q["connectionId"],"active":q["active"]}});return};if p=="set-worker-availability"{u:=st.Users[fmt.Sprint(q["workerId"])];if u==nil{fail(w,404,"not_found");return};u["available"]=q["available"];u["capacityUnits"]=q["capacityUnits"];reply(w,200,M{"data":q});return};if p=="update-user-access"{u:=st.Users[fmt.Sprint(q["userId"])];if u==nil{fail(w,404,"not_found");return};for k,v:=range q{if k!="userId"{u[k]=v}};reply(w,201,M{"data":u});return};if p=="update-sample-type"{t:=st.Types[fmt.Sprint(q["sampleTypeId"])];if t==nil{fail(w,404,"not_found");return};for k,v:=range q{if k!="sampleTypeId"{t[k]=v}};reply(w,201,M{"data":t});return};if p=="read-journey-plan"{j:=st.Journeys[fmt.Sprint(q["journeyId"])];if j==nil{fail(w,404,"not_found");return};reply(w,200,M{"data":j});return};if p=="read-serviceability-snapshot"{a:=[]any{};for _,l:=range st.Locations{f:=l["functions"].(M);if f["collection_point"]==true{c:=l["coordinate"].(M);a=append(a,M{"locationId":l["locationId"],"name":l["name"],"latitude":c["latitude"],"longitude":c["longitude"],"coverageKm":l["coverageKm"]})}};reply(w,200,M{"data":M{"version":1,"regions":a}});return};reply(w,200,M{"data":M{"status":"accepted"}})}
