package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"
)

type M map[string]any
type Store struct {
	Users       map[string]M `json:"users"`
	Samples     map[string]M `json:"samples"`
	Journeys    map[string]M `json:"journeys"`
	Assign      map[string]M `json:"assignments"`
	Locations   map[string]M `json:"locations"`
	Connections map[string]M `json:"connections"`
	Types       map[string]M `json:"types"`
	Handoffs    map[string]M `json:"handoffs"`
	Audit       []M          `json:"audit"`
	Seq         int          `json:"seq"`
	mu          sync.Mutex
}

var st Store

const stateFile = "/workspace/.lab-state.json"

func id() string {
	b := make([]byte, 16)
	rand.Read(b)
	return fmt.Sprintf("%s-%s-4%s-8%s-%s", hex.EncodeToString(b[:4]), hex.EncodeToString(b[4:6]), hex.EncodeToString(b[6:8])[1:], hex.EncodeToString(b[8:10])[1:], hex.EncodeToString(b[10:]))
}
func now() string { return time.Now().UTC().Format(time.RFC3339) }
func initStore() {
	st = Store{Users: map[string]M{}, Samples: map[string]M{}, Journeys: map[string]M{}, Assign: map[string]M{}, Locations: map[string]M{}, Connections: map[string]M{}, Types: map[string]M{}, Handoffs: map[string]M{}, Audit: []M{}}
	if b, e := os.ReadFile(stateFile); e == nil {
		json.Unmarshal(b, &st)
	}
	if st.Users == nil {
		st.Users = map[string]M{}
	}
	if len(st.Types) == 0 {
		for _, x := range []struct {
			n string
			c bool
			t float64
		}{{"Amber", false, 20}, {"Indigo", false, 20}, {"Frost", true, 4}, {"Pulse", false, 20}} {
			q := id()
			st.Types[q] = M{"sampleTypeId": q, "name": x.n, "qualifiedCollectorRequired": true, "requiredQualification": x.n, "containerType": "standard", "temperatureMinC": 0.0, "temperatureMaxC": x.t, "incompatibleSampleTypes": []any{}, "requiresCooledRoute": x.c, "batchingAllowed": x.n != "Pulse"}
		}
	}
	save()
}
func audit(actor, role, action, typ, eid string, details M) {
	st.Seq++
	st.Audit = append(st.Audit, M{"auditId": fmt.Sprint(st.Seq), "actorId": actor, "role": role, "actorRole": role, "action": action, "entityType": typ, "entityId": eid, "success": true, "occurredAt": now(), "details": details})
}

func save() { b, _ := json.Marshal(st); os.WriteFile(stateFile, b, 0600) }
func reply(w http.ResponseWriter, c int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(c)
	json.NewEncoder(w).Encode(v)
}
func fail(w http.ResponseWriter, c int, s string) {
	reply(w, c, M{"error": strings.ReplaceAll(s, "_", " "), "code": s})
}
func body(r *http.Request) (M, bool) {
	var x M
	d := json.NewDecoder(r.Body)
	d.DisallowUnknownFields()
	if d.Decode(&x) != nil {
		return nil, false
	}
	return x, true
}
func roles(u M) []any { r, _ := u["roles"].([]any); return r }
func has(u M, want ...string) bool {
	for _, r := range roles(u) {
		for _, w := range want {
			if r == w {
				return true
			}
		}
	}
	return false
}
func auth(r *http.Request) (string, M, bool) {
	t := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
	for k, u := range st.Users {
		if u["token"] == t && u["active"] == true {
			return k, u, true
		}
	}
	return "", nil, false
}
func require(w http.ResponseWriter, r *http.Request, a ...string) (string, M, bool) {
	uid, u, ok := auth(r)
	if !ok {
		fail(w, 401, "unauthorized")
		return "", nil, false
	}
	if len(a) > 0 && !has(u, a...) {
		fail(w, 403, "forbidden")
		return "", nil, false
	}
	return uid, u, true
}
func cap(n int) M {
	return M{"capacityUnits": n, "reservedUnits": 0, "availableUnits": n, "cooledCapacityUnits": 0, "cooledReservedUnits": 0, "cooledAvailableUnits": 0}
}
func tl(s M) []any { x, _ := s["timeline"].([]any); return x }
func event(s M, actor, role, action string) {
	st.Seq++
	s["timeline"] = append(tl(s), M{"eventId": st.Seq, "action": action, "actorId": actor, "role": role, "entityType": "sample", "entityId": s["sampleId"], "success": true, "occurredAt": now(), "details": M{}})
}
func distance(a, b M) float64 {
	la, _ := a["latitude"].(float64)
	lo, _ := a["longitude"].(float64)
	lb, _ := b["latitude"].(float64)
	lob, _ := b["longitude"].(float64)
	return math.Hypot(la-lb, lo-lob) * 111
}
func service(q M) (bool, string, string, string) {
	if st.Types[fmt.Sprint(q["sampleTypeId"])] == nil {
		return false, "no_accepting_laboratory", "", ""
	}
	o, _ := q["origin"].(M)
	near := false
	for _, l := range st.Locations {
		f, _ := l["functions"].(M)
		co, _ := l["coordinate"].(M)
		if l["active"] == true && f["collection_point"] == true && distance(o, co) <= 5 {
			near = true
		}
	}
	if !near {
		return false, "outside_service_coverage", "", ""
	}
	lab := ""
	for k, l := range st.Locations {
		f, _ := l["functions"].(M)
		if l["active"] == true && f["laboratory"] == true {
			for _, a := range l["acceptedSampleTypeIds"].([]any) {
				if a == q["sampleTypeId"] {
					lab = k
				}
			}
		}
	}
	if lab == "" {
		return false, "no_accepting_laboratory", "", ""
	}
	return true, "serviceable", lab, time.Now().Add(time.Hour).UTC().Format(time.RFC3339)
}
func main() {
	initStore()
	if len(st.Users) == 0 {
		username, password := os.Getenv("ADMIN_USERNAME"), os.Getenv("ADMIN_PASSWORD")
		if username != "" && password != "" {
			userID := id()
			st.Users[userID] = M{"userId": userID, "username": username, "password": password, "fullName": "Initial Administrator", "roles": []any{"administrator", "dispatcher"}, "qualifications": []any{}, "certifications": []any{}, "active": true, "activeRole": "administrator", "available": true, "capacityUnits": 1}
			save()
		}
	}
	http.HandleFunc("/ready", func(w http.ResponseWriter, r *http.Request) { reply(w, 200, M{"status": "ready"}) })
	http.HandleFunc("/api/", api)
	http.HandleFunc("/", ui)
	fmt.Println("Listening on 8080")
	http.ListenAndServe("127.0.0.1:8080", nil)
}
func api(w http.ResponseWriter, r *http.Request) {
	st.mu.Lock()
	defer st.mu.Unlock()
	p := strings.TrimPrefix(r.URL.Path, "/api/")
	if r.Method == "GET" {
		get(w, r, p)
		return
	}
	q, ok := body(r)
	if !ok {
		fail(w, 400, "invalid_json")
		return
	}
	post(w, r, p, q)
	save()
}
func get(w http.ResponseWriter, r *http.Request, p string) {
	uid, u, ok := require(w, r)
	if !ok {
		return
	}
	switch {
	case p == "ui/bootstrap":
