	}
	ws := []any{}
	for _, u := range st.Users {
		av := u["available"] == true
		ws = append(ws, M{"workerId": u["userId"], "fullName": u["fullName"], "roles": u["roles"], "available": av, "status": map[bool]string{true: "available", false: "unavailable"}[av], "capacityUnits": u["capacityUnits"], "assignmentCount": 0, "locationStale": true})
	}
