			fail(w, 403, "forbidden")
			return
		}
		l := st.Locations[fmt.Sprint(q["laboratoryId"])]
		if l == nil {
			fail(w, 404, "not_found")
			return
		}
		a, _ := l["acceptedSampleTypeIds"].([]any)
		if q["accepts"] == true {
			a = append(a, q["sampleTypeId"])
		}
		l["acceptedSampleTypeIds"] = a
		reply(w, 200, M{"data": M{"acceptanceId": id(), "accepts": q["accepts"]}})
	case "configure-capacity":
		if !admin() && !has(u, "node_handler", "laboratory_team") {
			fail(w, 403, "forbidden")
			return
		}
		for _, l := range st.Locations {
			if l["locationId"] == q["resourceId"] {
				n := int(q["capacityUnits"].(float64))
				c := cap(n)
				if z, ok := q["cooledCapacityUnits"].(float64); ok {
					c["cooledCapacityUnits"] = int(z)
					c["cooledAvailableUnits"] = int(z)
