		reply(w, 200, M{"data": M{"sampleId": s["sampleId"], "status": s["state"].(M)["status"], "sealed": s["sealed"], "completedLegIds": []any{}, "activeReplacementPlanIds": []any{}, "timeline": tl(s), "activeJourneyId": s["activeJourneyId"], "currentHolderId": s["currentHolderId"], "locationStale": s["locationStale"]}})
