	if !yes {
		fail(w, 409, reason)
		return
	}
	sid, rid, jid := id(), id(), id()
	t := st.Types[fmt.Sprint(q["sampleTypeId"])]
	s := M{"sampleId": sid, "requestId": rid, "requesterId": q["requesterId"], "origin": q["origin"], "originType": q["originType"], "requestedAt": q["requestedAt"], "deliveryDeadline": q["deliveryDeadline"], "sampleTypeId": q["sampleTypeId"], "containerType": t["containerType"], "temperatureMinC": t["temperatureMinC"], "temperatureMaxC": t["temperatureMaxC"], "incompatibleSampleTypes": t["incompatibleSampleTypes"], "serviceability": "serviceable", "activeAssignmentIds": []any{}, "state": M{"status": "planned"}, "timeline": []any{}, "activeJourneyId": jid, "targetLaboratoryId": lab, "locationStale": true, "sealed": pre, "currentHolderId": uid}
	event(s, uid, role, "sample_registered")
