}
func assignment(w http.ResponseWriter, uid, role, p string, q M) {
	a := st.Assign[fmt.Sprint(q["assignmentId"])]
	if a == nil {
		fail(w, 404, "not_found")
		return
	}
	if a["workerId"] != uid {
		fail(w, 403, "ineligible_worker")
		return
	}
	if p == "accept-assignment" {
		a["status"] = "accepted"
		reply(w, 201, M{"data": M{"assignmentId": a["assignmentId"], "workerId": uid, "status": "accepted"}})
		return
	}
	if p == "decline-assignment" {
		a["status"] = "declined"
		reply(w, 201, M{"data": M{"assignmentId": a["assignmentId"], "status": "declined"}})
		return
	}
	a["status"] = q["status"]
	reply(w, 201, M{"data": M{"assignmentId": a["assignmentId"], "sampleId": a["sampleId"], "status": q["status"]}})
}
