		u := st.Users[fmt.Sprint(q["workerId"])]
		if u == nil {
			fail(w, 404, "not_found")
			return
		}
		u["available"] = q["available"]
		u["capacityUnits"] = q["capacityUnits"]
		reply(w, 200, M{"data": q})
		return
	}
	if p == "update-user-access" {
